BEGIN;
CREATE SCHEMA IF NOT EXISTS orcafacil;
CREATE TABLE IF NOT EXISTS orcafacil.support_queues ("Id" uuid PRIMARY KEY,"AccountId" uuid NULL,"Name" varchar(120) NOT NULL,"Description" text NOT NULL DEFAULT '',"Level" varchar(16) NOT NULL,"IsGlobal" boolean NOT NULL DEFAULT false,"IsActive" boolean NOT NULL DEFAULT true,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_support_queues_scope_name ON orcafacil.support_queues(COALESCE("AccountId",'00000000-0000-0000-0000-000000000000'::uuid),"Name") WHERE NOT "IsDeleted";
CREATE TABLE IF NOT EXISTS orcafacil.support_queue_members ("Id" uuid PRIMARY KEY,"UserId" uuid NOT NULL,"QueueId" uuid NOT NULL REFERENCES orcafacil.support_queues("Id"),"Level" varchar(16) NOT NULL,"IsLeader" boolean NOT NULL DEFAULT false,"IsActive" boolean NOT NULL DEFAULT true,"MaxOpenTickets" integer NULL CHECK ("MaxOpenTickets" IS NULL OR "MaxOpenTickets">0),"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_support_queue_member ON orcafacil.support_queue_members("QueueId","UserId") WHERE NOT "IsDeleted";
CREATE TABLE IF NOT EXISTS orcafacil.support_ticket_sla_policies ("Id" uuid PRIMARY KEY,"AccountId" uuid NULL,"PlanId" uuid NULL,"PriorityId" uuid NULL,"QueueId" uuid NULL,"Name" varchar(120) NOT NULL,"FirstResponseMinutes" integer NOT NULL CHECK("FirstResponseMinutes">0),"ResolutionMinutes" integer NOT NULL CHECK("ResolutionMinutes">0),"BusinessHoursOnly" boolean NOT NULL DEFAULT false,"BusinessDaysJson" text NOT NULL DEFAULT '[1,2,3,4,5]',"StartTime" time NULL,"EndTime" time NULL,"IsActive" boolean NOT NULL DEFAULT true,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.support_ticket_events ("Id" uuid PRIMARY KEY,"AccountId" uuid NOT NULL,"TicketId" uuid NOT NULL REFERENCES orcafacil.support_tickets("Id"),"ActorUserId" uuid NULL,"Type" varchar(50) NOT NULL,"Details" varchar(2000) NOT NULL DEFAULT '',"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_support_ticket_events_timeline ON orcafacil.support_ticket_events("AccountId","TicketId","CreatedAt");
CREATE TABLE IF NOT EXISTS orcafacil.support_ticket_sla_events ("Id" uuid PRIMARY KEY,"AccountId" uuid NOT NULL,"TicketId" uuid NOT NULL REFERENCES orcafacil.support_tickets("Id"),"Type" varchar(50) NOT NULL,"OccurredAt" timestamptz NOT NULL,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_support_sla_event_once ON orcafacil.support_ticket_sla_events("TicketId","Type") WHERE NOT "IsDeleted";
CREATE TABLE IF NOT EXISTS orcafacil.support_ticket_escalations ("Id" uuid PRIMARY KEY,"AccountId" uuid NOT NULL,"TicketId" uuid NOT NULL,"FromQueueId" uuid NOT NULL,"ToQueueId" uuid NOT NULL,"EscalatedByUserId" uuid NOT NULL,"Reason" varchar(1000) NOT NULL,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.support_ticket_csat_surveys ("Id" uuid PRIMARY KEY,"AccountId" uuid NOT NULL,"TicketId" uuid NOT NULL,"RequesterUserId" uuid NOT NULL,"TokenHash" varchar(64) NOT NULL,"ExpiresAt" timestamptz NOT NULL,"RespondedAt" timestamptz NULL,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_support_csat_ticket ON orcafacil.support_ticket_csat_surveys("TicketId") WHERE NOT "IsDeleted";
CREATE TABLE IF NOT EXISTS orcafacil.support_ticket_csat_responses ("Id" uuid PRIMARY KEY,"AccountId" uuid NOT NULL,"SurveyId" uuid NOT NULL,"Rating" integer NOT NULL CHECK("Rating" BETWEEN 1 AND 5),"Comment" varchar(2000) NULL,"WasResolved" boolean NOT NULL,"TimelinessAdequate" boolean NOT NULL,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_support_csat_response ON orcafacil.support_ticket_csat_responses("SurveyId") WHERE NOT "IsDeleted";
CREATE TABLE IF NOT EXISTS orcafacil.support_incidents ("Id" uuid PRIMARY KEY,"Title" varchar(180) NOT NULL,"Description" text NOT NULL,"Severity" varchar(8) NOT NULL,"Status" varchar(24) NOT NULL,"StartedAt" timestamptz NOT NULL,"ResolvedAt" timestamptz NULL,"CreatedByUserId" uuid NOT NULL,"IsPublicApproved" boolean NOT NULL DEFAULT false,"ResolutionSummary" text NULL,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.support_incident_impacted_accounts ("Id" uuid PRIMARY KEY,"IncidentId" uuid NOT NULL REFERENCES orcafacil.support_incidents("Id"),"AccountId" uuid NOT NULL,"ShowPublicMessage" boolean NOT NULL DEFAULT false,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_support_incident_account ON orcafacil.support_incident_impacted_accounts("IncidentId","AccountId") WHERE NOT "IsDeleted";
ALTER TABLE orcafacil.support_tickets ADD COLUMN IF NOT EXISTS "QueueId" uuid NULL, ADD COLUMN IF NOT EXISTS "AssignedToUserId" uuid NULL, ADD COLUMN IF NOT EXISTS "SlaPolicyId" uuid NULL, ADD COLUMN IF NOT EXISTS "FirstResponseDueAt" timestamptz NULL, ADD COLUMN IF NOT EXISTS "ResolutionDueAt" timestamptz NULL, ADD COLUMN IF NOT EXISTS "FirstRespondedAt" timestamptz NULL, ADD COLUMN IF NOT EXISTS "Source" varchar(32) NOT NULL DEFAULT 'Internal', ADD COLUMN IF NOT EXISTS "Impact" varchar(24) NOT NULL DEFAULT 'SingleUser', ADD COLUMN IF NOT EXISTS "Urgency" varchar(24) NOT NULL DEFAULT 'Normal';
ALTER TABLE orcafacil.support_ticket_messages ADD COLUMN IF NOT EXISTS "Type" varchar(24) NOT NULL DEFAULT 'PublicReply';
CREATE TABLE IF NOT EXISTS orcafacil.support_problem_records ("Id" uuid PRIMARY KEY,"Title" varchar(180) NOT NULL,"Description" text NOT NULL,"Status" varchar(24) NOT NULL,"RootCause" text NULL,"Workaround" text NULL,"Resolution" text NULL,"IsPublicApproved" boolean NOT NULL DEFAULT false,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.support_knowledge_articles ("Id" uuid PRIMARY KEY,"AccountId" uuid NULL,"Title" varchar(180) NOT NULL,"Content" text NOT NULL,"Visibility" varchar(20) NOT NULL DEFAULT 'Internal',"IsPublished" boolean NOT NULL DEFAULT false,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_support_knowledge_scope ON orcafacil.support_knowledge_articles("AccountId","IsPublished") WHERE NOT "IsDeleted";
CREATE TABLE IF NOT EXISTS orcafacil.support_macros ("Id" uuid PRIMARY KEY,"AccountId" uuid NULL,"Name" varchar(120) NOT NULL,"Title" varchar(180) NOT NULL,"Content" text NOT NULL,"Visibility" varchar(20) NOT NULL DEFAULT 'Internal',"IsActive" boolean NOT NULL DEFAULT true,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.support_shift_schedules ("Id" uuid PRIMARY KEY,"UserId" uuid NOT NULL,"QueueId" uuid NOT NULL,"StartAt" timestamptz NOT NULL,"EndAt" timestamptz NOT NULL,"IsOnCall" boolean NOT NULL DEFAULT false,"CreatedAt" timestamptz NOT NULL DEFAULT now(),"UpdatedAt" timestamptz NULL,"IsDeleted" boolean NOT NULL DEFAULT false, CHECK("EndAt">"StartAt"));
COMMIT;
